import{_ as e,o as a,c as d,a4 as n}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"HomeSense L2 混合检索（v2）测试数据报告","description":"","frontmatter":{"title":"HomeSense L2 混合检索（v2）测试数据报告","date":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"posts/HomeSense-L2-混合检索测试报告.md","filePath":"posts/HomeSense-L2-混合检索测试报告.md"}'),o={name:"posts/HomeSense-L2-混合检索测试报告.md"};function i(l,t,s,r,h,c){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="homesense-l2-混合检索-v2-测试数据报告" tabindex="-1">HomeSense L2 混合检索（v2）测试数据报告 <a class="header-anchor" href="#homesense-l2-混合检索-v2-测试数据报告" aria-label="Permalink to &quot;HomeSense L2 混合检索（v2）测试数据报告&quot;">​</a></h1><blockquote><p>日期：2026-09-02 组件：<code>pkg/workflowmatch</code>（fingerprint + BM25 + embedding + RRF + 意图卡片反例否决） 模型：bge-small-zh-v1.5 INT8 ONNX（512 维，本地推理 ~33ms） 测试环境：本机 x86_64（AMD Ryzen 5 5500U），阈值 0.65</p></blockquote><hr><h2 id="_1-架构-v2" tabindex="-1">1. 架构（v2） <a class="header-anchor" href="#_1-架构-v2" aria-label="Permalink to &quot;1. 架构（v2）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>workflow_match:</span></span>
<span class="line"><span>  ① fingerprint SHA256       精确命中即返回       0.1ms</span></span>
<span class="line"><span>  ② BM25 词面 (CJK 二元组)    召回「回家/到家了」类   ~0ms</span></span>
<span class="line"><span>  ③ embedding 语义 (512 维)   召回换词说法            ~33ms</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>  RRF 融合 (k=60) → 按 chain 聚合 → 反例否决 → top1 + confidence</span></span></code></pre></div><ul><li>意图卡片：每个 workflow 的 <code>intents</code>（多个 positive 锚点，逐条入库）、<code>negative_examples</code>（反例否决）、<code>confusable</code>。</li><li>反例否决规则：候选 chain 的任一反例与 query 的 cos ≥ 该 chain 最佳正例 cos - 0.02 且 ≥ 0.55 → 整链否决。</li><li>置信度 = <code>max(cos, lexical coverage)</code>（coverage 为 query 词命中文档比例，修掉归一化 BM25 假高分）。</li></ul><hr><h2 id="_2-测试集-a-回归测试-55-例" tabindex="-1">2. 测试集 A：回归测试（55 例） <a class="header-anchor" href="#_2-测试集-a-回归测试-55-例" aria-label="Permalink to &quot;2. 测试集 A：回归测试（55 例）&quot;">​</a></h2><p><strong>声明：此测试有水分。</strong> 测试短语大多直接写入了意图卡片的 <code>intents</code>，靠 fingerprint 精确命中（等于&quot;背答案&quot;），<strong>不代表真实泛化能力</strong>。</p><p>结果：55/55 (100%)，0 误报 —— 该数字仅证明&quot;卡片内说法都能命中&quot;，不反映新说法效果。</p><h3 id="覆盖亮点-卡片内" tabindex="-1">覆盖亮点（卡片内） <a class="header-anchor" href="#覆盖亮点-卡片内" aria-label="Permalink to &quot;覆盖亮点（卡片内）&quot;">​</a></h3><ul><li>小声点 / 开冷气 / 我到家了 / 到家了 → fingerprint 直接命中（v1 全漏报）</li><li>离家模式 → away_mode 正确，且被 home_mode 的 negative 否决不再撞回</li><li>无关输入（天气/外卖/新闻联播）全部拒绝</li></ul><hr><h2 id="_3-测试集-b-hold-out-泛化测试-51-例-卡片仅-2-3-锚点-测试说法未入卡片" tabindex="-1">3. 测试集 B：Hold-out 泛化测试（51 例，卡片仅 2-3 锚点，测试说法未入卡片） <a class="header-anchor" href="#_3-测试集-b-hold-out-泛化测试-51-例-卡片仅-2-3-锚点-测试说法未入卡片" aria-label="Permalink to &quot;3. 测试集 B：Hold-out 泛化测试（51 例，卡片仅 2-3 锚点，测试说法未入卡片）&quot;">​</a></h2><p><strong>这是真实泛化能力的数字。</strong></p><p>结果：<strong>51 例命中 43 (84%)，误报 1</strong>（thr 0.65）</p><h3 id="正确泛化-38-例-说明混合检索核心有效" tabindex="-1">正确泛化（38 例，说明混合检索核心有效） <a class="header-anchor" href="#正确泛化-38-例-说明混合检索核心有效" aria-label="Permalink to &quot;正确泛化（38 例，说明混合检索核心有效）&quot;">​</a></h3><ul><li>我回家了/到家了/回来了/下班回来了 → home_mode（embedding/BM25 泛化）</li><li>出门了/我出门去了/打开离家模式/出门上班/离开家 → away_mode</li><li>看电影/我想看个电影/放个电影/今晚看部电影 → movie_mode</li><li>帮我开下灯/开下灯/把客厅灯亮起来/打开客厅的灯/灯打开 → on_lights</li><li>帮我关下灯/关下灯/灯关上 → off_lights</li><li>投一下屏/把手机投到大屏/投屏手机/手机投屏/投屏到大屏 → cast_tv</li><li>把声音弄小一点/音量要小/给我调小声 → volume_down</li><li>声音大点/调大声/再来大点声 → volume_up</li><li>把空调打开/开下空调/空调开开/制冷/开一下制冷 → ac_cool</li></ul><h3 id="漏报-7-例" tabindex="-1">漏报（7 例） <a class="header-anchor" href="#漏报-7-例" aria-label="Permalink to &quot;漏报（7 例）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>说法</th><th>期望</th><th>实际</th><th>原因</th></tr></thead><tbody><tr><td>打开电影模式</td><td>movie_mode</td><td>nil (0.00)</td><td>泛化不足</td></tr><tr><td>把客厅灯灭了</td><td>off_lights</td><td>nil</td><td>「灭了」未覆盖，coverage=0.4 &lt; 0.65</td></tr><tr><td>熄灯</td><td>off_lights</td><td>→ on_lights (0.74)</td><td><strong>反义陷阱</strong>：emb 跑偏到开灯</td></tr><tr><td>小声点</td><td>volume_down</td><td>nil (0.00)</td><td>词面无重叠</td></tr><tr><td>声音小点</td><td>volume_down</td><td>nil (0.00)</td><td>词面无重叠</td></tr><tr><td>把声音放大</td><td>volume_up</td><td>→ volume_down (0.80)</td><td><strong>方向性反了</strong>：把声音X 强overlap到「调小」</td></tr><tr><td>音量放大</td><td>volume_up</td><td>→ volume_down (0.81)</td><td>同上，方向性反了</td></tr></tbody></table><h3 id="误报-1-例" tabindex="-1">误报（1 例） <a class="header-anchor" href="#误报-1-例" aria-label="Permalink to &quot;误报（1 例）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>说法</th><th>期望</th><th>实际</th><th>原因</th></tr></thead><tbody><tr><td>我要睡觉了</td><td>拒绝</td><td>→ away_mode (0.69)</td><td>「我要」前缀撞上「我要出门了」</td></tr></tbody></table><hr><h2 id="_4-方向性漏报分析-核心硬伤" tabindex="-1">4. 方向性漏报分析（核心硬伤） <a class="header-anchor" href="#_4-方向性漏报分析-核心硬伤" aria-label="Permalink to &quot;4. 方向性漏报分析（核心硬伤）&quot;">​</a></h2><p>embedding 模型对反义词方向（开/关、放大/调小、熄/开）本质不敏感：</p><ul><li>熄灯 → 被认成「开灯」（0.74）</li><li>把声音放大 → 被认成「调小」（0.80）</li><li>把客厅灯灭了 → 完全漏掉</li></ul><p>这是业界公开弱点（ACL 2024《Can Your Model Tell a Negation from an Implicature?》证实所有 embedding 模型对否定/反义语义理解差）。<strong>不是实现 bug，是模型能力天花板。</strong></p><p>当前缓解手段 = 意图卡片 hard-negative（把反义词写进 <code>negative_examples</code>），能钉死已知坑，但对未预见的反义表达无效。</p><hr><h2 id="_5-l1-规则拦截-方向性第一道防线" tabindex="-1">5. L1 规则拦截（方向性第一道防线） <a class="header-anchor" href="#_5-l1-规则拦截-方向性第一道防线" aria-label="Permalink to &quot;5. L1 规则拦截（方向性第一道防线）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>打开电视 → device=电视 cap=turn_on   ✅ 拦截</span></span>
<span class="line"><span>关电视   → device=电视 cap=turn_off  ✅ 拦截</span></span>
<span class="line"><span>开客厅灯 → device=灯  cap=turn_on    ✅ 拦截</span></span>
<span class="line"><span>关空调   → device=空调 cap=turn_off  ✅ 拦截</span></span></code></pre></div><p>简单开/关+设备指令由 <code>rule_engine</code> 直接消化，不进 L2。</p><hr><h2 id="_6-结论" tabindex="-1">6. 结论 <a class="header-anchor" href="#_6-结论" aria-label="Permalink to &quot;6. 结论&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>卡片内召回</td><td>100%</td><td>背答案性质，不具参考价值</td></tr><tr><td>真实泛化召回</td><td><strong>84%</strong></td><td>hold-out 51 例</td></tr><tr><td>真实误报</td><td>1/51</td><td>「我要睡觉了」→ away</td></tr><tr><td>方向性</td><td><strong>硬伤</strong></td><td>反义/方向仍需 hard-negative 逐个钉死</td></tr><tr><td>延迟</td><td>fingerprint 0.1ms / BM25 ~0ms / embedding ~33ms</td><td></td></tr><tr><td>体积</td><td>~42MB</td><td>模型24MB + libonnxruntime 18MB + binary</td></tr></tbody></table><h3 id="改进空间" tabindex="-1">改进空间 <a class="header-anchor" href="#改进空间" aria-label="Permalink to &quot;改进空间&quot;">​</a></h3><ol><li>补 hard-negative（每个方向坑写反例）→ 治标</li><li>加 NLI 模型做方向软校准（见桌面另一份报告）→ 治本方向，但引入体积</li><li>高置信本地接管、低置信云端 LLM（业界混合路由）→ 最终形态</li></ol>`,37)])])}const u=e(o,[["render",i]]);export{m as __pageData,u as default};
